import 'package:dio/dio.dart';import 'package:flutter/foundation.dart';abstract class Failure {  final String errMessage;  const Failure(this.errMessage);}class ServerFailure extends Failure {  ServerFailure(super.errMessage);  factory ServerFailure.unauthorized() {    return ServerFailure("🔐 Unauthorized access. Please login ");  }  factory ServerFailure.fromDioError(DioException dioError) {    return ServerFailure(ApiErrorHandler.getErrorMessage(dioError));  }  factory ServerFailure.fromResponse(int? statusCode, dynamic response) {    final message = ApiErrorHandler.getMessageFromResponse(response);    if (statusCode == 401 || statusCode == 403) {      return ServerFailure.unauthorized();    } else if (message != null) {      return ServerFailure(message);    } else {      // Provide a generic error based on status code      if (statusCode == 404) {        return ServerFailure("Resource not found");      } else if (statusCode == 500) {        return ServerFailure("Server error. Please try again later.");      } else {        return ServerFailure("Something went wrong. Please try again later.");      }    }  }}class ApiErrorHandler {  // Main function to get error message from any error  static String getErrorMessage(dynamic error) {    if (error is DioException) {      // Check for internet connectivity first      if (error.type == DioExceptionType.connectionError) {        return "No internet connection, please check your network";      }      // Connection and network errors      if (error.type == DioExceptionType.connectionTimeout ||          error.type == DioExceptionType.sendTimeout ||          error.type == DioExceptionType.receiveTimeout) {        return "Network timeout, please try again";      }      // Handle API response with error      if (error.type == DioExceptionType.badResponse) {        final responseMessage = getMessageFromResponse(error.response?.data);        if (responseMessage != null) {          // Return the exact response message if available          return responseMessage;        }      }      // Log unexpected Dio errors      if (kDebugMode) {        print("❌ Unexpected Dio Error: ${error.toString()}");      }      return "Something went wrong. Please try again later.";    } else {      // Log unexpected non-Dio errors      if (kDebugMode) {        print("❌ Unexpected Error: ${error.toString()}");      }      return "Something went wrong. Please try again later.";    }  }  // Function to extract message from API response  // Returns null if no valid message was found  static String? getMessageFromResponse(dynamic response) {    if (response == null) return null;    try {      if (response is Map<String, dynamic>) {        // Check for message field first (most common)        if (response.containsKey('message') && response['message'] != null) {          if (response['message'] is String) {            final message = response['message'];            if (isValidMessage(message)) {              return message;            }          }        }        // Check for error field        if (response.containsKey('error') && response['error'] != null) {          if (response['error'] is String) {            final error = response['error'];            if (isValidMessage(error)) {              return error;            }          }        }        // Check for errors object that might contain messages        if (response.containsKey('errors') && response['errors'] != null) {          final errors = response['errors'];          if (errors is Map<String, dynamic>) {            // Get the first error message from the map            final firstErrorKey = errors.keys.first;            final errorValue = errors[firstErrorKey];            if (errorValue is List && errorValue.isNotEmpty) {              final firstError = errorValue.first.toString();              if (isValidMessage(firstError)) {                return firstError;              }            } else if (errorValue != null) {              final errorString = errorValue.toString();              if (isValidMessage(errorString)) {                return errorString;              }            }          } else if (errors is List && errors.isNotEmpty) {            final firstError = errors.first.toString();            if (isValidMessage(firstError)) {              return firstError;            }          }        }        // Log the raw response for debugging if no message was found        if (kDebugMode) {          print("❌ Unhandled API Error Response: $response");        }        return null;      } else if (response is String) {        // If the response is directly a string        if (isValidMessage(response)) {          return response;        }        return null;      }    } catch (e) {      // Log any exception during parsing      if (kDebugMode) {        print("❌ Error parsing API response: $e");        print("❌ Original response: $response");      }    }    return null;  }  // Helper method to check if a message is valid  static bool isValidMessage(String message) {    if (message.isEmpty) return false;    // Ignore if message is just a URL    if (isUrl(message)) {      if (kDebugMode) {        print("❌ Ignoring URL as error message: $message");      }      return false;    }    // Ignore messages that are too short or unusual    if (message.length < 3) return false;    // Additional validation could be added here    return true;  }  // Helper method to check if a string is a URL  static bool isUrl(String text) {    // Simple URL detection    final urlPattern = RegExp(      r'^(https?:\/\/)?(www\.)?[-a-zA-Z0-9@:%._\+~#=]{1,256}\.[a-zA-Z0-9()]{1,6}\b([-a-zA-Z0-9()@:%_\+.~#?&//=]*)$',      caseSensitive: false,    );    return urlPattern.hasMatch(text.trim());  }}